import os
from google_auth_oauthlib.flow import InstalledAppFlow

def pkce_login(payload, config=None):
    config = config or {}
    client_id = config.get('CLIENT_ID') or os.environ.get('GOOGLE_CLIENT_ID')
    if not client_id:
        raise ValueError('CLIENT_ID is required in config or GOOGLE_CLIENT_ID env var')
    client_secret = config.get('CLIENT_SECRET', '')
    redirect_base = config.get('REDIRECT_URI', 'http://localhost')
    scopes = payload.get('scopes', ['openid', 'profile', 'email'])
    client_config = {
        'installed': {
            'client_id': client_id,
            'client_secret': client_secret,
            'redirect_uris': [redirect_base],
            'auth_uri': 'https://accounts.google.com/o/oauth2/auth',
            'token_uri': 'https://oauth2.googleapis.com/token',
        }
    }
    flow = InstalledAppFlow.from_client_config(client_config, scopes=scopes)
    credentials = flow.run_local_server(port=0)
    result = {
        'access_token': credentials.token,
        'refresh_token': credentials.refresh_token,
        'id_token': credentials.id_token,
    }
    return result
